using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEditor.AddressableAssets;using UnityEngine;using Rootborn.UI.Modern;
namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanInventoryBackpackTests{
[Test]public void BackpackUsesCrispNativeIconGeometryAndOwnAddress(){const string path="Assets/Art/UI/UrbanMolding/student_backpack.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(64,64)));Assert.That(s.pivot,Is.EqualTo(new Vector2(32,32)));Assert.That(s.pixelsPerUnit,Is.EqualTo(16));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));var e=AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path));Assert.That(e.address,Is.EqualTo("sprites/ui/urban-life/student-backpack"));}
[Test]public void ThemeResolvesBackpackWithoutReplacingExistingIcons(){var t=AssetDatabase.LoadAssetAtPath<UrbanUiThemeDefinition>("Assets/Data/UI/UrbanMoldingTheme.asset");var s=t.GetIcon("inventory-all");Assert.That(s,Is.Not.Null);Assert.That(s.name,Is.EqualTo("student_backpack"));foreach(var key in new[]{"journal","plan","town_map","discovery","chef","care","interior","training","time","energy","focus","money","school"})Assert.That(t.GetIcon(key),Is.Not.Null,key);}
[Test]public void InventoryAllTabUsesSharedThemeIconAndKeepsLayout(){var go=new GameObject("Inventory",typeof(RectTransform));try{go.AddComponent<ModernUiInventoryPanel>().Show();var icon=go.transform.Find("Tab_0/Icon");Assert.That(icon.GetComponent<UrbanUiIcon>(),Is.Not.Null);Assert.That(new SerializedObject(icon.GetComponent<UrbanUiIcon>()).FindProperty("_key").stringValue,Is.EqualTo("inventory-all"));Assert.That(((RectTransform)icon).sizeDelta,Is.EqualTo(new Vector2(56,56)));for(int i=1;i<4;i++)Assert.That(go.transform.Find("Tab_"+i+"/Icon").GetComponent<UrbanUiIcon>(),Is.Not.Null);Assert.That(go.GetComponentsInChildren<UnityEngine.UI.ScrollRect>().Single().content.childCount,Is.EqualTo(Rootborn.Game.Common.Inventory.MaxSlots));}finally{Object.DestroyImmediate(go);}}
}}
